    44	export async function runHarness(options: RunHarnessOptions = {}): Promise<HarnessRunResult> {
    45	  const config = await loadHarnessConfig(options);
    46	  const registry = await createRunAdapterRegistry(config, options.adapters);
    47	  const outputRegistry = await createOutputProviderRegistry({
    48	    projectRoot: config.projectRoot,
    49	    outputRoot: config.outputRoot,
    50	    providers: config.output.providers,
    51	    visualization: config.visualization,
    52	  });
    53	  validateAdapterReferences(registry, Object.values(config.agents).map((agent) => agent.adapter));
    54	  const matrix = buildMatrix(config, options);
    55	  validateAdapterReferences(registry, matrix.map((entry) => entry.agent.adapter));
    56	  const concurrency = options.concurrency ?? 1;
    57	  const imageAgents = buildImageResolutionAgents(matrix);
    58	  let sharedImageResolution: Promise<ImageResolutionResult> | undefined;
    59	  const resolveSharedImage = options.refreshManagedImage && matrix.length > 0 && matrix.every((entry) => !entry.docker.image)
    60	    ? () => {
    61	      sharedImageResolution ??= resolveDockerImage({
    62	        projectRoot: config.projectRoot,
    63	        docker: matrix[0].docker,
    64	        selectedAgents: imageAgents,
    65	        adapterRegistry: registry,
    66	        refreshManagedImage: true,
    67	      });
    68	      return sharedImageResolution;
    69	    }
    70	    : undefined;
    71	  const judgeRunner = options.judgeRunner ?? createConfiguredJudgeRunner({ config, registry });
    72	  const cleanup = cleanupEnabled(options.cleanup);
    73	  const batch = createBatchInfo({
    74	    argv: options.cliArgs,
    75	    agents: unique(matrix.map((entry) => entry.agentName)),
    76	    caseCount: new Set(matrix.map((entry) => entry.testCase.id)).size,
    77	    runCount: matrix.length,
    78	  });
    79	  const results = await mapConcurrent(matrix, concurrency, (entry) => runTestCase(
    80	    config,
    81	    entry,
    82	    registry,
    83	    outputRegistry,
    84	    imageAgents,
    85	    judgeRunner,
    86	    options.refreshManagedImage,
    87	    resolveSharedImage,
    88	    batch,
    89	    cleanup,
    90	  ));
    91	  const cost = buildHarnessCostSummary(results);
    92	  const passAtK = buildPassAtKSummary(results);
    93	  const outputPath = await writeHarnessSummary(config, outputRegistry, registry, matrix, results, cost, passAtK, batch);
    94	
    95	  return {
    96	    pass: results.every((result) => result.pass),
    97	    results,
    98	    cost,
    99	    passAtK,
   100	    outputPath,
   101	  };
   102	}
