   104	export async function runTestCase(
   105	  config: LoadedHarnessConfig,
   106	  entry: MatrixEntry,
   107	  registry?: AdapterRegistry,
   108	  outputRegistry?: OutputProviderRegistry,
   109	  imageAgents?: ImageResolutionAgent[],
   110	  judgeRunner?: JudgeRunner,
   111	  refreshManagedImage?: boolean,
   112	  resolveImage?: () => Promise<ImageResolutionResult>,
   113	  batch?: BatchInfo,
