   138	      visualization: config.visualization,
   139	    });
   140	    dispatcher = await createOutputDispatcher({
   141	      projectRoot: config.projectRoot,
   142	      runId,
   143	      scenarioId: entry.testCase.id,
   144	      agentName: entry.agentName,
   145	      redactions,
   146	      providers: activeOutputRegistry.create({ runId, runDir, scenarioId: entry.testCase.id, agentName: entry.agentName }),
   147	    });
   148	
   149	    await dispatcher.emit({
   150	      type: 'run.started',
   151	      payload: {
   152	        runId,
   153	        scenarioId: entry.testCase.id,
   154	        caseId: entry.testCase.id,
   155	        agentName: entry.agentName,
   156	        attemptIndex: entry.attemptIndex,
   157	        attemptNumber: entry.attemptNumber,
   158	        attempts: entry.attempts,
   159	        runDir,
   160	        batch: activeBatch,
   161	        testCase: {
