   163	          description: entry.testCase.description,
   164	          suite: entry.testCase.suite,
   165	          sourcePath: entry.testCase.sourcePath,
   166	          stepCount: entry.testCase.steps.length,
   167	        },
   168	        agent: {
   169	          adapter: entry.agent.adapter,
   170	          label: entry.agent.label,
   171	          model: entry.agent.model,
   172	          provider: entry.agent.provider,
   173	        },
   174	        docker: {
   175	          image: entry.docker.image,
   176	          workspaceTarget: entry.workspace.containerPath,
   177	          configTarget: entry.docker.configRoot,
   178	        },
   179	        providerFailures: dispatcher.providerFailures,
   180	      },
   181	    });
   182	
   183	    const activeJudgeRunner = judgeRunner ?? createConfiguredJudgeRunner({ config, registry: adapterRegistry });
   184	    const adapter = adapterRegistry.require(entry.agent.adapter);
   185	    if (!adapter.applyMcpMocks && hasDeclaredMcpMocks(entry)) {
