   248	      testCaseId: entry.testCase.id,
   249	      agentName: entry.agentName,
   250	      runId,
   251	      runDir,
   252	      workspaceDir,
   253	      configDir,
   254	    };
   255	    let skipReason: string | undefined;
   256	
   257	    for (const [stepIndex, step] of entry.testCase.steps.entries()) {
