   290	      steps.push(execution.result);
   291	      context.continuation = execution.continuation;
   292	      skipReason = skipReasonForStep(execution.result);
   293	    }
   294	
   295	    const finalSnapshot = await snapshotWorkspace(workspaceDir, entry.workspace.ignore);
   296	    const workspace = diffWorkspace(beforeSnapshot, finalSnapshot);
   297	    await dispatcher.emit({ type: 'workspace.diff', payload: workspace });
   298	
   299	    const verifierArtifacts = await runVerifierArtifacts({
   300	      entry,
   301	      dispatcher,
   302	      runDir,
   303	      baseWorkspaceDir,
   304	      workspaceDir,
   305	      configDir,
   306	      dockerImage,
   307	      projectRoot: config.projectRoot,
   308	    });
   309	
   310	    const result = buildTestRunResult({
   311	      entry,
   312	      context,
   313	      steps,
   314	      workspace,
   315	      verifier: verifierArtifacts.verifier,
   316	      modelPatch: verifierArtifacts.modelPatch,
   317	      hiddenPatch: verifierArtifacts.hiddenPatch,
   318	      durationMs: Date.now() - runStartedAt,
   319	      scoring: config.scoring,
   320	      redactions,
   321	    });
   322	
   323	    await dispatcher.emit({ type: 'scenario.scoreSummary', payload: result.score });
   324	    await dispatcher.emit({ type: 'scenario.costSummary', payload: result.cost });
   325	    await dispatcher.emit({ type: 'run.result', payload: result });
   326	    const runVisualization = runVisualizationReportPayload(config, result);
   327	    if (runVisualization) await dispatcher.emit({ type: 'visualization.report', payload: runVisualization });
   328	    await dispatcher.emit({ type: 'run.summary', payload: buildRunSummary(result, dispatcher, activeBatch) });
   329	    await dispatcher.finalize({ status: outputStatusForRun(result.status) });
   330	    return result;
   331	  } catch (error) {
   332	    const message = error instanceof Error ? error.message : String(error);
   333	    const result = buildSetupErrorResult(entry, runId, runDir, steps, message, Date.now() - runStartedAt, redactions, config.scoring);
   334	
   335	    if (dispatcher) await persistErrorResult(config, dispatcher, result, currentStepId, activeBatch);
   336	    return result;
   337	  } finally {
   338	    if (cleanup) await Promise.all(cleanupPaths.map((path) => rm(path, { recursive: true, force: true })));
   339	  }
   340	}
