   535	      events,
   536	      workspace,
   537	      metadata,
   538	      mockCalls: mockCallSummaries,
   539	    }, {
   540	      judgeDefaults: input.config.judge,
   541	      judgeRunner: input.judgeRunner,
   542	      redactions: input.redactions,
   543	      onJudgeRecord: async (record) => {
   544	        await input.dispatcher.emit({ type: 'step.judge', stepId, payload: record });
   545	      },
   546	    });
   547	    for (const call of unmatchedStrictMocks) assertions.push(errorAssertion(call.error ?? `Unmatched ${call.surface} mock call: ${call.tool}`));
   548	    await input.dispatcher.emit({ type: 'step.assertions', stepId, payload: assertions });
   549	    assertionsEmitted = true;
   550	
   551	    const stepCost = buildStepCostReport({
   552	      adapterCost: events.cost,
   553	      assertions,
   554	      dimensions: costDimensions(input.entry, input.context, input.step, input.stepIndex, stepId),
   555	    });
