   379	function renderMatrix(runs, agents) {
   380	  var node = document.getElementById('matrix-table');
   381	  if (!runs.length) { node.innerHTML = emptyNote(); return; }
   382	  var agentNames = agents.map(function (agent) { return agent.name; });
   383	  var byCase = {};
   384	  for (var i = 0; i < runs.length; i++) {
   385	    var run = runs[i];
   386	    if (!byCase[run.caseId]) byCase[run.caseId] = { suite: suiteOf(run), cells: {} };
   387	    if (!byCase[run.caseId].cells[run.agentName]) byCase[run.caseId].cells[run.agentName] = [];
   388	    byCase[run.caseId].cells[run.agentName].push(run);
   389	  }
   390	  var caseIds = [];
   391	  for (var caseId in byCase) caseIds.push(caseId);
   392	  caseIds.sort(function (a, b) {
   393	    var sa = byCase[a].suite, sb = byCase[b].suite;
   394	    if (sa !== sb) return sa < sb ? -1 : 1;
   395	    return a < b ? -1 : a > b ? 1 : 0;
   396	  });
   397	  var maxCost = 0, maxDur = 0;
   398	  for (var c = 0; c < caseIds.length; c++) {
   399	    for (var a = 0; a < agentNames.length; a++) {
   400	      var rep = representative(byCase[caseIds[c]].cells[agentNames[a]]);
   401	      if (!rep) continue;
   402	      if (rep.cost && rep.cost.totalCost) maxCost = Math.max(maxCost, rep.cost.totalCost);
   403	      if (rep.durationMs) maxDur = Math.max(maxDur, rep.durationMs);
   404	    }
   405	  }
   406	  var html = ['<table class="matrix"><thead><tr><th>task</th>'];
   407	  for (var h = 0; h < agentNames.length; h++) html.push('<th>' + esc(agentNames[h]) + '</th>');
   408	  html.push('</tr></thead><tbody>');
   409	  var lastSuite = null;
   410	  for (var ci = 0; ci < caseIds.length; ci++) {
   411	    var entry = byCase[caseIds[ci]];
   412	    if (entry.suite !== lastSuite) {
   413	      lastSuite = entry.suite;
   414	      html.push('<tr class="suite-row"><td colspan="' + (agentNames.length + 1) + '">' + esc(entry.suite) + '</td></tr>');
   415	    }
   416	    html.push('<tr><td class="case">' + esc(caseIds[ci]) + '</td>');
   417	    for (var ai = 0; ai < agentNames.length; ai++) {
   418	      var cellRuns = entry.cells[agentNames[ai]] || [];
   419	      html.push(matrixCell(caseIds[ci], agentNames[ai], cellRuns, maxCost, maxDur));
   420	    }
   421	    html.push('</tr>');
   422	    var open = state.openDetail;
   423	    if (open && open.caseId === caseIds[ci]) {
   424	      html.push('<tr class="detail"><td colspan="' + (agentNames.length + 1) + '">' + detailContent(entry.cells[open.agent] || []) + '</td></tr>');
   425	    }
   426	  }
   427	  html.push('</tbody></table>');
   428	  node.innerHTML = html.join('');
   429	  node.querySelectorAll('td.cell').forEach(function (cell) {
   430	    cell.addEventListener('click', function () {
   431	      var caseId = cell.dataset.case, agent = cell.dataset.agent;
   432	      var open = state.openDetail;
   433	      state.openDetail = open && open.caseId === caseId && open.agent === agent ? null : { caseId: caseId, agent: agent };
   434	      renderAll();
   435	    });
   436	  });
   437	}
   438	
   439	function representative(cellRuns) {
   440	  if (!cellRuns || !cellRuns.length) return null;
   441	  var best = cellRuns[0];
   442	  for (var i = 1; i < cellRuns.length; i++) {
   443	    if (cellRuns[i].pass && !best.pass) best = cellRuns[i];
   444	    else if (cellRuns[i].pass === best.pass && sortStamp(cellRuns[i]) > sortStamp(best)) best = cellRuns[i];
   445	  }
   446	  return best;
   447	}
   448	
   449	function matrixCell(caseId, agent, cellRuns, maxCost, maxDur) {
   450	  var rep = representative(cellRuns);
   451	  if (!rep) return '<td class="cell" data-case="' + esc(caseId) + '" data-agent="' + esc(agent) + '"><span class="cell-meta">—</span></td>';
   452	  var costPct = maxCost && rep.cost && rep.cost.totalCost ? Math.round((rep.cost.totalCost / maxCost) * 100) : 0;
   453	  var durPct = maxDur && rep.durationMs ? Math.round((rep.durationMs / maxDur) * 100) : 0;
   454	  var attempts = cellRuns.length > 1 ? ' ×' + cellRuns.length : '';
   455	  return '<td class="cell" data-case="' + esc(caseId) + '" data-agent="' + esc(agent) + '">'
   456	    + '<span class="dot ' + esc(rep.status) + '"></span>' + esc(rep.status) + attempts
   457	    + ' <span class="cell-meta">' + fmtDur(rep.durationMs) + ' · ' + fmtUSD(rep.cost ? rep.cost.totalCost : undefined)
   458	    + ' · ' + fmtTokens(rep.cost ? rep.cost.totalTokens : undefined) + '</span>'
   459	    + '<div class="microbars"><div class="microbar cost"><i style="width:' + costPct + '%"></i></div>'
   460	    + '<div class="microbar"><i style="width:' + durPct + '%"></i></div></div></td>';
   461	}
   462	
   463	function detailContent(cellRuns) {
   464	  if (!cellRuns.length) return 'No runs.';
   465	  var html = [];
   466	  for (var i = 0; i < cellRuns.length; i++) {
   467	    var run = cellRuns[i];
   468	    var link = run.indexHref ? ' · <a href="' + esc(runHref(run)) + '">run report</a>' : '';
   469	    html.push('<div>' + esc(run.runId) + ' — ' + esc(run.status)
   470	      + (run.attemptNumber ? ' · attempt ' + run.attemptNumber : '')
   471	      + ' · ' + fmtDur(run.durationMs) + ' · ' + fmtUSD(run.cost ? run.cost.totalCost : undefined)
   472	      + ' · in ' + fmtTokens(run.cost ? run.cost.inputTokens : undefined)
   473	      + ' / cached ' + fmtTokens(run.cost ? run.cost.cachedInputTokens : undefined)
   474	      + ' / out ' + fmtTokens(run.cost ? run.cost.outputTokens : undefined)
   475	      + ' · ' + esc((run.models || []).join(' + ') || run.model || '')
   476	      + (run.error ? ' · ' + esc(run.error) : '') + link + '</div>');
   477	  }
   478	  return html.join('');
   479	}
   480	
   481	function runHref(run) {
   482	  if (location.protocol === 'http:' || location.protocol === 'https:') {
   483	    return '/runs/' + encodeURIComponent(run.runId) + '/index.html';
   484	  }
   485	  return run.indexHref;
   486	}
