   488	// ---------- strip plots ----------
   489	
   490	function renderStrip(nodeId, runs, agents, metric) {
   491	  var node = document.getElementById(nodeId);
   492	  var values = runs.filter(function (run) { return metricValue(run, metric) !== undefined && GRADED[run.status]; });
   493	  if (!values.length || !agents.length) { node.innerHTML = emptyNote(); return; }
   494	  var maxVal = 0;
   495	  for (var i = 0; i < values.length; i++) maxVal = Math.max(maxVal, metricValue(values[i], metric));
   496	  maxVal = maxVal * 1.05 || 1;
   497	  var width = 560, rowH = 36, padL = 96, padR = 16, padT = 8;
   498	  var height = padT + agents.length * rowH + 28;
   499	  var svg = ['<svg viewBox="0 0 ' + width + ' ' + height + '" xmlns="http://www.w3.org/2000/svg">'];
   500	  for (var ai = 0; ai < agents.length; ai++) {
   501	    var rowY = padT + ai * rowH + rowH / 2;
   502	    svg.push('<text x="' + (padL - 8) + '" y="' + (rowY + 4) + '" text-anchor="end" class="name">' + esc(agents[ai].name) + '</text>');
   503	    svg.push('<line x1="' + padL + '" y1="' + rowY + '" x2="' + (width - padR) + '" y2="' + rowY + '" stroke="rgba(45,49,66,0.08)" stroke-width="0.8"/>');
   504	    var agentRuns = values.filter(function (run) { return run.agentName === agents[ai].name; });
   505	    for (var ri = 0; ri < agentRuns.length; ri++) {
   506	      var run = agentRuns[ri];
   507	      var x = padL + (metricValue(run, metric) / maxVal) * (width - padL - padR);
   508	      var jitter = (hashJitter(run.runId) - 0.5) * 16;
   509	      var fill = run.pass ? '#4f5d75' : '#eb6c36';
   510	      svg.push('<circle cx="' + x + '" cy="' + (rowY + jitter) + '" r="4" fill="' + fill + '" opacity="0.75"><title>'
   511	        + esc(run.caseId + ' — ' + (metric === 'cost' ? fmtUSD(metricValue(run, metric)) : fmtDur(metricValue(run, metric)))) + '</title></circle>');
   512	    }
   513	  }
   514	  var baseY = padT + agents.length * rowH + 8;
   515	  for (var t = 0; t <= 4; t++) {
   516	    var val = (maxVal / 4) * t;
   517	    var tx = padL + (val / maxVal) * (width - padL - padR);
   518	    svg.push('<text x="' + tx + '" y="' + (baseY + 10) + '" text-anchor="middle" class="axis">'
   519	      + (metric === 'cost' ? fmtUSD(val) : fmtDur(val)) + '</text>');
   520	  }
   521	  svg.push('</svg>');
   522	  node.innerHTML = svg.join('')
   523	    + '<div class="legend"><span><i style="background:#4f5d75"></i>solved</span><span><i style="background:#eb6c36"></i>failed</span></div>';
   524	}
