   533	function renderTokens(agents) {
   534	  var node = document.getElementById('token-bars');
   535	  var withTokens = agents.filter(function (agent) { return agent.cached + agent.input + agent.output > 0; });
   536	  if (!withTokens.length) { node.innerHTML = emptyNote(); return; }
   537	  var maxTotal = 0;
   538	  for (var i = 0; i < withTokens.length; i++) {
   539	    maxTotal = Math.max(maxTotal, withTokens[i].cached + withTokens[i].input + withTokens[i].output);
   540	  }
   541	  var width = 1120, rowH = 32, padL = 96, padR = 80, padT = 4;
   542	  var height = padT + withTokens.length * rowH + 8;
   543	  var svg = ['<svg viewBox="0 0 ' + width + ' ' + height + '" xmlns="http://www.w3.org/2000/svg">'];
   544	  var colors = { cached: '#7a8399', input: '#4f5d75', output: '#2d3142' };
   545	  for (var ai = 0; ai < withTokens.length; ai++) {
   546	    var agent = withTokens[ai];
   547	    var total = agent.cached + agent.input + agent.output;
   548	    var y = padT + ai * rowH + 6;
   549	    var scale = (width - padL - padR) / maxTotal;
   550	    var x = padL;
   551	    svg.push('<text x="' + (padL - 8) + '" y="' + (y + 12) + '" text-anchor="end" class="name">' + esc(agent.name) + '</text>');
   552	    var parts = [['cached', agent.cached], ['input', agent.input], ['output', agent.output]];
   553	    for (var p = 0; p < parts.length; p++) {
   554	      var w = parts[p][1] * scale;
   555	      if (w > 0) {
