   558	      }
   559	    }
   560	    svg.push('<text x="' + (x + 8) + '" y="' + (y + 12) + '" class="val">' + fmtTokens(total) + '</text>');
   561	  }
   562	  svg.push('</svg>');
   563	  node.innerHTML = svg.join('')
   564	    + '<div class="legend"><span><i style="background:#7a8399;border-radius:2px"></i>cached reads</span>'
   565	    + '<span><i style="background:#4f5d75;border-radius:2px"></i>input</span>'
   566	    + '<span><i style="background:#2d3142;border-radius:2px"></i>output</span></div>';
   567	}
