   577	  renderMatrix(runs, agents);
   578	  renderStrip('duration-strip', runs, agents, 'duration');
   579	  renderStrip('cost-strip', runs, agents, 'cost');
   580	  renderTokens(agents);
   581	}
   582	
   583	initState();
   584	renderControls();
   585	renderAll();
