   809	interface PrepareCall {
   810	  stepId: string;
   811	  stepIndex: number;
   812	  workspaceDir: string;
   813	  continuation?: AdapterContinuation;
   814	}
   815	
   816	interface ScopedPrepareCall {
   817	  stepId: string;
   818	  args?: string[];
   819	  env?: string[];
   820	  agentConfig?: Record<string, unknown>;
   821	  stepConfig?: Record<string, unknown>;
   822	}
   823	
   824	interface ScopedStepOutput {
   825	  argv: string[];
   826	  env: { agent?: string | null; base?: string | null; first?: string | null; second?: string | null; one?: string | null; two?: string | null };
   827	  config: Record<string, unknown>;
   828	}
