   986	let index = 1;
   987	let workdir;
   988	const mounts = [];
   989	const env = { PATH: process.env.PATH };
   990	while (index < args.length) {
   991	  const arg = args[index];
   992	  if (arg === '--rm') {
   993	    index += 1;
   994	    continue;
   995	  }
   996	  if (arg === '--name' || arg === '--user') {
   997	    index += 2;
   998	    continue;
   999	  }
  1000	  if (arg === '--network') {
  1001	    env.HARNESS_FAKE_DOCKER_NETWORK = args[index + 1];
  1002	    index += 2;
  1003	    continue;
  1004	  }
  1005	  if (arg === '--workdir') {
  1006	    workdir = args[index + 1];
  1007	    index += 2;
  1008	    continue;
  1009	  }
  1010	  if (arg === '--mount') {
  1011	    mounts.push(parseMount(args[index + 1]));
  1012	    index += 2;
  1013	    continue;
  1014	  }
  1015	  if (arg === '-e') {
  1016	    const spec = args[index + 1];
  1017	    const equals = spec.indexOf('=');
  1018	    if (equals === -1) {
  1019	      if (process.env[spec] !== undefined) env[spec] = process.env[spec];
  1020	    } else {
  1021	      env[spec.slice(0, equals)] = spec.slice(equals + 1);
  1022	    }
  1023	    index += 2;
  1024	    continue;
  1025	  }
  1026	  if (arg.startsWith('-')) {
  1027	    index += 1;
  1028	    continue;
  1029	  }
  1030	  break;
  1031	}
  1032	
  1033	index += 1;
  1034	const command = args[index];
  1035	const commandArgs = args.slice(index + 1);
  1036	if (!command) process.exit(0);
  1037	if (command === 'fake-sleep') {
  1038	  setInterval(() => {}, 60_000);
  1039	} else {
  1040	  const result = spawnSync(command, commandArgs, {
  1041	    cwd: workdir ? mapPath(workdir) : process.cwd(),
  1042	    env,
  1043	    encoding: 'utf8',
  1044	    stdio: ['ignore', 'pipe', 'pipe'],
  1045	  });
