  1047	  if (result.stderr) process.stderr.write(result.stderr);
  1048	  if (result.error) {
  1049	    console.error(result.error.message);
  1050	    process.exit(127);
  1051	  }
  1052	  process.exit(result.status ?? (result.signal ? 1 : 0));
  1053	}
  1054	
  1055	function parseMount(value) {
  1056	  const mount = {};
  1057	  for (const part of value.split(',')) {
  1058	    const equals = part.indexOf('=');
  1059	    if (equals !== -1) mount[part.slice(0, equals)] = part.slice(equals + 1);
  1060	  }
  1061	  return mount;
  1062	}
  1063	
  1064	function mapPath(path) {
