    45	    const optionalProviders = hasFileProvider ? this.input.providers.filter((entry) => !isFileProvider(entry.provider)) : [];
    46	
    47	    for (const entry of requiredProviders) {
    48	      await initializeProvider(entry, this.initializeInput(entry));
    49	      this.activeProviders.push(entry);
    50	    }
    51	
    52	    for (const entry of optionalProviders) {
    53	      try {
    54	        await initializeProvider(entry, this.initializeInput(entry));
    55	        this.activeProviders.push(entry);
    56	      } catch (error) {
