    67	      sequence: ++this.sequence,
    68	      type: input.type,
    69	      timestamp: input.timestamp ?? new Date().toISOString(),
    70	      scenarioId: input.scenarioId ?? this.input.scenarioId,
    71	      agentName: input.agentName ?? this.input.agentName,
