    91	      refs.push(await writeProviderBlob(entry, blob));
    92	    }
    93	
    94	    for (const entry of optionalProviders) {
    95	      try {
    96	        refs.push(await writeProviderBlob(entry, blob));
    97	      } catch (error) {
    98	        this.failures.push(providerFailure(entry.provider, 'writeBlob', error));
    99	      }
