   115	    const hasFileProvider = this.activeProviders.some((entry) => isFileProvider(entry.provider));
   116	    const requiredProviders = hasFileProvider ? this.activeProviders.filter((entry) => isFileProvider(entry.provider)) : this.activeProviders;
