+  const record: LocalBatchRecord = {
+    schemaVersion: 1,
+    batch: cloneBatch(input.batch),
+    status: 'completed',
+    expectedRunCount: input.expectedRunCount,
+    runIds: [...input.runIds],
+    completedAt: input.completedAt ?? new Date().toISOString(),
+  };
