import { mkdir, readFile, readdir, writeFile } from 'node:fs/promises';
import { isAbsolute, relative, resolve } from 'node:path';
import type { ResultsPublishConfig, ResultsStoreConfig } from '../../config/schema.js';
import type { LocalBatchRecord } from '../../runner/batch-record.js';
import { readLocalBatchRecord } from '../../runner/batch-record.js';
import { scanWorkspaceRuns, type ScannedTaskRun } from '../../visualization/scan.js';
import type { PublicBatchIndexEntry, PublicBatchManifest, PublicBatchTotals, PublicCostSummary, PublicResultsIndex, PublicResultsStore, PublicRunSummary, PublicResultsObjectOptions, PublicBatchValidity } from './types.js';

export const REAL_BATCH_ID = /^\d{8}-\d{6}-[0-9a-f]{4}$/;
export const ARCHIVE_OBJECTS = ['manifest.json', 'results.html', 'results.csv'] as const;

export function validateBatchId(id: string): void { if (!REAL_BATCH_ID.test(id)) throw new Error(`Invalid batch ID: ${id}`); }
export function validateKey(key: string): void {
  if (!key || key.includes('\\') || key.startsWith('/') || key.split('/').some((part) => !part || part === '.' || part === '..')) throw new Error(`Unsafe storage key: ${key}`);
}
export function validatePrefix(prefix: string): void { validateKey(prefix); }

export class FilePublicResultsStore implements PublicResultsStore {
  constructor(public readonly root: string) {}
  async get(key: string): Promise<Uint8Array | undefined> {
    const path = this.path(key); try { return await readFile(path); } catch (e) { if ((e as NodeJS.ErrnoException).code === 'ENOENT') return undefined; throw e; }
  }
  async put(key: string, content: Uint8Array, _options: PublicResultsObjectOptions): Promise<void> { const path = this.path(key); await mkdir(resolve(path, '..'), { recursive: true }); await writeFile(path, content); }
  async list(prefix: string): Promise<string[]> {
    validateKey(prefix); const out: string[] = [];
    const walk = async (dir: string, base: string): Promise<void> => { let entries: Awaited<ReturnType<typeof readdir>>; try { entries = await readdir(dir, { withFileTypes: true }); } catch { return; } for (const entry of entries) { const key = base ? `${base}/${entry.name}` : entry.name; if (entry.isDirectory()) await walk(resolve(dir, entry.name), key); else if (key.startsWith(prefix)) out.push(key); } };
    await walk(this.root, ''); return out.sort();
  }
  private path(key: string): string { validateKey(key); const path = resolve(this.root, ...key.split('/')); const rel = relative(resolve(this.root), path); if (rel.startsWith('..') || isAbsolute(rel)) throw new Error(`Storage key escapes root: ${key}`); return path; }
}

export function projectBatch(batchId: string, runs: readonly ScannedTaskRun[], batchMeta?: { startedAt?: string; label?: string }): PublicBatchManifest {
  validateBatchId(batchId); const selected = runs.filter((run) => run.batchId === batchId); if (!selected.length) throw new Error(`Batch has no scanned task runs: ${batchId}`);
  const publicRuns = selected.map(toPublicRun).sort((a, b) => a.caseId.localeCompare(b.caseId) || a.agentName.localeCompare(b.agentName) || (a.attemptNumber ?? 0) - (b.attemptNumber ?? 0) || a.runId.localeCompare(b.runId));
  return { schemaVersion: 1, batchId, startedAt: batchMeta?.startedAt, label: batchMeta?.label, suites: unique(publicRuns.map((r) => r.suite)), cases: unique(publicRuns.map((r) => r.caseId)), agents: unique(publicRuns.map((r) => r.agentName)), totals: totals(publicRuns), runs: publicRuns };
}

function toPublicRun(run: ScannedTaskRun): PublicRunSummary {
  return compact({ runId: run.runId, caseId: run.caseId, agentName: run.agentName, suite: run.suite, attemptNumber: run.attemptNumber, attempts: run.attempts, status: run.status, pass: run.pass, startedAt: run.startedAt, durationMs: run.durationMs, exitCode: run.exitCode, score: run.score, provider: run.provider, model: run.model, models: run.models ? unique(run.models) : undefined, assertions: run.assertions, cost: run.cost ? compact(run.cost) : undefined });
}

function totals(runs: readonly PublicRunSummary[]): PublicBatchTotals {
  const out: PublicBatchTotals = { runs: runs.length, passed: count(runs, 'passed'), failed: count(runs, 'failed'), errors: count(runs, 'error'), skipped: count(runs, 'skipped'), timeouts: count(runs, 'timeout'), incomplete: count(runs, 'incomplete') };
  const durations = runs.map((r) => r.durationMs).filter((n): n is number => n !== undefined); if (durations.length) out.durationMs = durations.reduce((a, b) => a + b, 0);
  const costs = runs.map((r) => r.cost).filter((c): c is PublicCostSummary => Boolean(c)); if (costs.length) out.cost = sumCosts(costs);
  return out;
}
function sumCosts(costs: PublicCostSummary[]): PublicCostSummary {
  const currencies = unique(costs.map((c) => c.currency)); const out: PublicCostSummary = currencies.length === 1 && currencies[0] ? { currency: currencies[0] } : {};
  for (const key of ['totalCost', 'inputTokens', 'outputTokens', 'cachedInputTokens', 'reasoningTokens', 'totalTokens', 'requests'] as const) { const values = costs.map((c) => c[key]).filter((n): n is number => n !== undefined); if (values.length && (key !== 'totalCost' || currencies.length === 1)) out[key] = values.reduce((a, b) => a + b, 0); }
  return out;
}
function count(runs: readonly PublicRunSummary[], status: PublicRunSummary['status']): number { return runs.filter((r) => r.status === status).length; }
function unique(values: Array<string | undefined>): string[] { return [...new Set(values.filter((v): v is string => Boolean(v)))].sort(); }
function compact<T extends Record<string, unknown>>(value: T): T { return Object.fromEntries(Object.entries(value).filter(([, v]) => v !== undefined)) as T; }

export function renderPublicCsv(manifest: PublicBatchManifest): string {
  const headers = ['runId','caseId','suite','agentName','attemptNumber','attempts','status','pass','startedAt','durationMs','exitCode','score','provider','model','models','totalCost','currency','inputTokens','outputTokens','cachedInputTokens','reasoningTokens','totalTokens','requests'];
  const rows = manifest.runs.map((r) => [r.runId,r.caseId,r.suite,r.agentName,r.attemptNumber,r.attempts,r.status,r.pass,r.startedAt,r.durationMs,r.exitCode,r.score,r.provider,r.model,r.models?.join('+'),r.cost?.totalCost,r.cost?.currency,r.cost?.inputTokens,r.cost?.outputTokens,r.cost?.cachedInputTokens,r.cost?.reasoningTokens,r.cost?.totalTokens,r.cost?.requests].map(csv).join(','));
  return `${headers.join(',')}\n${rows.join('\n')}\n`;
}
function csv(v: unknown): string { const s = v === undefined || v === null ? '' : String(v); return /[",\n]/.test(s) ? `"${s.replaceAll('"', '""')}"` : s; }

export function renderPublicBatchHtml(manifest: PublicBatchManifest): string {
  const data = JSON.stringify(manifest).replaceAll('<', '\\u003c');
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Harness Evals — ${escapeHtml(manifest.batchId)}</title><style>body{font:14px system-ui;margin:2rem;color:#222}table{border-collapse:collapse;width:100%}th,td{padding:.5rem;border-bottom:1px solid #ddd;text-align:left}code{font-family:monospace}</style></head><body><p><a href="../../index.html">Public results archive</a></p><h1>Batch ${escapeHtml(manifest.batchId)}</h1><p>${manifest.totals.runs} runs · ${manifest.totals.passed} passed · ${manifest.totals.failed} failed · ${manifest.totals.errors} errors</p><table><thead><tr><th>Case</th><th>Agent</th><th>Status</th><th>Pass</th><th>Score</th><th>Duration</th><th>Cost</th></tr></thead><tbody>${manifest.runs.map((r) => `<tr><td>${escapeHtml(r.caseId)}</td><td>${escapeHtml(r.agentName)}</td><td>${escapeHtml(r.status)}</td><td>${r.pass ? 'yes' : 'no'}</td><td>${r.score ?? '—'}</td><td>${r.durationMs ?? '—'}</td><td>${r.cost?.totalCost ?? '—'}${r.cost?.currency ? ` ${escapeHtml(r.cost.currency)}` : ''}</td></tr>`).join('')}</tbody></table><script type="application/json" id="manifest">${data}</script></body></html>`;
}

export function renderPublicIndexHtml(): string {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Harness Evals — Public Results</title><style>body{font:14px system-ui;margin:2rem;color:#222}table{border-collapse:collapse;width:100%}th,td{padding:.5rem;border-bottom:1px solid #ddd;text-align:left}.controls{display:flex;gap:.5rem;flex-wrap:wrap;margin:1rem 0}</style></head><body><h1>Public results</h1><div class="controls"><input id="suite" placeholder="suite"><input id="case" placeholder="case"><input id="agent" placeholder="agent"><select id="validity"><option value="">all validity</option><option>valid</option><option>invalid</option><option>superseded</option></select><select id="status"><option value="">any status</option><option>passed</option><option>failed</option><option>error</option><option>timeout</option><option>incomplete</option><option>skipped</option></select></div><table><thead><tr><th>Batch</th><th>Validity</th><th>Runs</th><th>Pass</th><th>Failed</th><th>Errors</th><th>Links</th></tr></thead><tbody id="batches"></tbody></table><script>(async()=>{const index=await fetch('./index.json').then(r=>r.json());const esc=s=>String(s).replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',"'":'&#39;'}[c]));const fields=['suite','case','agent','validity','status'];function render(){const f=Object.fromEntries(fields.map(x=>[x,document.getElementById(x).value]));let rows=index.batches.filter(b=>(!f.suite||b.suites.includes(f.suite))&&(!f.case||b.cases.includes(f.case))&&(!f.agent||b.agents.includes(f.agent))&&(!f.validity||b.validity===f.validity)&&(!f.status||b.totals[{passed:'passed',failed:'failed',error:'errors',timeout:'timeouts',incomplete:'incomplete',skipped:'skipped'}[f.status]]>0));document.getElementById('batches').innerHTML=rows.map((b,i)=>'<tr><td>'+esc(b.batchId)+(i===0?' <b>latest</b>':'')+'</td><td>'+esc(b.validity)+(b.validityNote?' — '+esc(b.validityNote):'')+'</td><td>'+b.totals.runs+'</td><td>'+b.totals.passed+'</td><td>'+b.totals.failed+'</td><td>'+b.totals.errors+'</td><td><a href="'+esc(b.reportPath)+'">HTML</a> <a href="'+esc(b.manifestPath)+'">JSON</a> <a href="'+esc(b.csvPath)+'">CSV</a></td></tr>').join('')}fields.forEach(x=>document.getElementById(x).addEventListener('input',render));render()})().catch(e=>document.body.insertAdjacentHTML('beforeend','<p>'+String(e)+'</p>'));</script></body></html>`;
}
function escapeHtml(value: string): string { return value.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#39;'); }

export interface ArchiveBuild { manifest: PublicBatchManifest; manifestBytes: Uint8Array; htmlBytes: Uint8Array; csvBytes: Uint8Array; entry: PublicBatchIndexEntry; }
export function buildArchive(batchId: string, runs: readonly ScannedTaskRun[], batchMeta?: { startedAt?: string; label?: string }): ArchiveBuild {
  const manifest = projectBatch(batchId, runs, batchMeta); const enc = new TextEncoder(); const entry: PublicBatchIndexEntry = { batchId, startedAt: manifest.startedAt, label: manifest.label, validity: 'valid', suites: manifest.suites, cases: manifest.cases, agents: manifest.agents, totals: manifest.totals, manifestPath: `batches/${batchId}/manifest.json`, reportPath: `batches/${batchId}/results.html`, csvPath: `batches/${batchId}/results.csv` };
  return { manifest, manifestBytes: enc.encode(`${JSON.stringify(manifest,null,2)}\n`), htmlBytes: enc.encode(renderPublicBatchHtml(manifest)), csvBytes: enc.encode(renderPublicCsv(manifest)), entry };
}

export function validateBatchRecord(record: LocalBatchRecord | undefined, batchId: string, runs: readonly ScannedTaskRun[], allowUnfinalized = false): void {
  validateBatchId(batchId); const selected = runs.filter((r) => r.batchId === batchId); if (!selected.length) throw new Error(`Batch has no scanned task runs: ${batchId}`);
  if (!record) { if (!allowUnfinalized) throw new Error(`Batch has no completed local batch record: ${batchId}`); return; }
