export function createStore(config: ResultsStoreConfig): PublicResultsStore { if (config.type !== 'file') throw new Error('S3 store is not available in this build'); if (!config.root) throw new Error('File results store root is required'); return new FilePublicResultsStore(config.root); }
export async function readIndex(store: PublicResultsStore, root: string): Promise<PublicResultsIndex> { const bytes = await store.get(`${root}/v1/index.json`); if (!bytes) return { schemaVersion: 1, updatedAt: new Date(0).toISOString(), batches: [] }; const value = JSON.parse(new TextDecoder().decode(bytes)) as PublicResultsIndex; if (value.schemaVersion !== 1 || !Array.isArray(value.batches)) throw new Error('Invalid public results index'); return value; }
export function sortIndex(index: PublicResultsIndex): PublicResultsIndex { return { ...index, batches: [...index.batches].sort((a,b)=>(b.startedAt??'').localeCompare(a.startedAt??'') || b.batchId.localeCompare(a.batchId)) }; }
export function indexHtmlBytes(): Uint8Array { return new TextEncoder().encode(renderPublicIndexHtml()); }
export function batchRecordFor(projectRoot: string, batchId: string): Promise<LocalBatchRecord | undefined> { return readLocalBatchRecord(projectRoot, batchId); }
export { scanWorkspaceRuns };

