export function escapeHtml(value: string): string {
  return value.replace(/[&<>"']/g, (character) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' })[character] ?? character);
}

function renderRunRow(run: PublicRunSummary): string {
  const attributes = `data-status="${escapeAttribute(run.status)}" data-agent="${escapeAttribute(run.agentName)}" data-case="${escapeAttribute(run.caseId)}"`;
  const assertions = run.assertions ? `${run.assertions.passed}/${run.assertions.total} (${run.assertions.failedRequired} required failed)` : '—';
  return `<tr ${attributes}><td>${escapeHtml(run.caseId)}</td><td>${escapeHtml(run.suite ?? '—')}</td><td>${escapeHtml(run.agentName)}</td><td>${run.attemptNumber ?? ''}</td><td>${run.attempts ?? ''}</td><td>${escapeHtml(run.status)}</td><td>${run.pass ? 'yes' : 'no'}</td><td>${escapeHtml(run.startedAt ?? '—')}</td><td>${run.score ?? ''}</td><td>${run.durationMs === undefined ? '' : `${run.durationMs} ms`}</td><td>${run.exitCode === undefined ? '' : run.exitCode === null ? 'null' : run.exitCode}</td><td>${escapeHtml(run.provider ?? '—')}</td><td>${escapeHtml(run.models?.join('|') ?? run.model ?? '—')}</td><td>${escapeHtml(assertions)}</td><td>${renderUsage(run)}</td><td>${renderCost(run)}</td></tr>`;
}

function renderTotals(manifest: PublicBatchManifest): string {
  const totals = manifest.totals;
  const values = [`${totals.durationMs ?? '—'}${totals.durationMs === undefined ? '' : ' ms'}`];
  if (totals.cost?.totalCost !== undefined) values.push(`${totals.cost.totalCost}${totals.cost.currency ? ` ${totals.cost.currency}` : ''}`);
  if (totals.cost?.totalTokens !== undefined) values.push(`${totals.cost.totalTokens} tokens`);
  return values.join(' · ');
}

function renderCost(run: PublicRunSummary): string {
  if (!run.cost || run.cost.totalCost === undefined) return '—';
  return escapeHtml(`${run.cost.totalCost}${run.cost.currency ? ` ${run.cost.currency}` : ''}`);
}

function renderUsage(run: PublicRunSummary): string {
  if (!run.cost) return '—';
  const values = [
    run.cost.inputTokens === undefined ? undefined : `in ${run.cost.inputTokens}`,
    run.cost.outputTokens === undefined ? undefined : `out ${run.cost.outputTokens}`,
    run.cost.cachedInputTokens === undefined ? undefined : `cached ${run.cost.cachedInputTokens}`,
    run.cost.reasoningTokens === undefined ? undefined : `reasoning ${run.cost.reasoningTokens}`,
    run.cost.totalTokens === undefined ? undefined : `total ${run.cost.totalTokens}`,
    run.cost.requests === undefined ? undefined : `requests ${run.cost.requests}`,
  ].filter((value): value is string => value !== undefined);
  return escapeHtml(values.length ? values.join(', ') : '—');
}

function escapeAttribute(value: string): string {
  return escapeHtml(value);
}

function safeJson(value: PublicBatchManifest | PublicResultsIndex): string {
  return JSON.stringify(value).replace(/[<>&\u2028\u2029]/g, (character) => ({ '<': '\\u003C', '>': '\\u003E', '&': '\\u0026', '\u2028': '\\u2028', '\u2029': '\\u2029' })[character] ?? character);
}

